//! The generated Rust source: the table as a slice of string literals,
//! with the command that regenerates it in its header.

use std::fmt::Write as _;

use crate::compose::Table;

/// The source text of the glyph table module. `command` is the line that
/// regenerates the file, written into the header so the next person
/// knows how; `origin` names where the sources came from.
#[must_use]
pub fn rust_source(table: &Table, origin: &str, command: &str) -> String {
    let mut out = String::new();
    let _ = writeln!(
        out,
        "//! The Newstroke glyph table, generated by `newstroke_dev`: do not edit.\n\
         //!\n\
         //! Source: {origin}\n\
         //!\n\
         //! Regenerate with `{command}`.\n\
         //!\n\
         //! One string per code point from [`FIRST`], in KiCad's stroke-font\n\
         //! encoding: the first two characters are the left and right bearings,\n\
         //! then pairs of characters are x and y offset from `R`, with ` R`\n\
         //! lifting the pen between strokes. [`super`] decodes it.\n"
    );
    let _ = writeln!(
        out,
        "/// The code point of the first glyph.\npub(super) const FIRST: u32 = {:#06x};\n",
        table.first
    );
    let _ = writeln!(
        out,
        "/// The glyphs, one per code point from [`FIRST`].\n#[rustfmt::skip]\npub(super) const GLYPHS: &[&str] = &["
    );
    for (index, glyph) in table.glyphs.iter().enumerate() {
        let code = table.first + u32::try_from(index).unwrap_or(u32::MAX);
        let _ = write!(
            out,
            "    \"{}\",",
            glyph.replace('\\', "\\\\").replace('"', "\\\"")
        );
        if index % 16 == 0 {
            let _ = write!(out, " // U+{code:04X}");
        }
        out.push('\n');
    }
    out.push_str("];\n");
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_source_escapes_what_a_string_literal_must() {
        let table = Table {
            first: 0x20,
            glyphs: vec!["JZ".to_owned(), "H\\K\"".to_owned()],
        };
        let source = rust_source(&table, "a tarball", "cargo run --bin newstroke_dev -- a b");
        assert!(source.contains("const FIRST: u32 = 0x0020;"));
        assert!(
            source.contains("    \"JZ\", // U+0020\n    \"H\\\\K\\\"\",\n];"),
            "{source}"
        );
        assert!(source.contains("Regenerate with `cargo run --bin newstroke_dev -- a b`."));
    }
}
